import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";import"./gzh-BO4QB3XE.js";import"./zsxq-BKcsYlFO.js";var i=JSON.parse(`{"path":"/blog/2025/Other/01-How-To-Install-And-Use-DeepSeek-R-1-In-Your-Local-PC.html","title":"How To Install And Use DeepSeek R-1 In Your Local PC","lang":"zh-CN","frontmatter":{"title":"How To Install And Use DeepSeek R-1 In Your Local PC","date":"2025-02-01T14:50:06.000Z","author":"AI悦创","isOriginal":true,"icon":"blog","sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"description":"everyone seems to be talking about DeepSeek R-1, the new open-source AI language model made by a Chinese AI firm, DeepSeek. Some users claim it’s on par with, or even better tha...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"How To Install And Use DeepSeek R-1 In Your Local PC\\",\\"image\\":[\\"https://bornforthis.cn/gzh.jpg\\",\\"https://bornforthis.cn/zsxq.jpg\\"],\\"datePublished\\":\\"2025-02-01T14:50:06.000Z\\",\\"dateModified\\":\\"2025-04-10T23:49:50.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"AI悦创\\"}]}"],["meta",{"property":"og:url","content":"https://bornforthis.cn/blog/2025/Other/01-How-To-Install-And-Use-DeepSeek-R-1-In-Your-Local-PC.html"}],["meta",{"property":"og:site_name","content":"AI悦创-Python一对一辅导"}],["meta",{"property":"og:title","content":"How To Install And Use DeepSeek R-1 In Your Local PC"}],["meta",{"property":"og:description","content":"everyone seems to be talking about DeepSeek R-1, the new open-source AI language model made by a Chinese AI firm, DeepSeek. Some users claim it’s on par with, or even better tha..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://bornforthis.cn/gzh.jpg"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2025-04-10T23:49:50.000Z"}],["meta",{"property":"article:author","content":"AI悦创"}],["meta",{"property":"article:published_time","content":"2025-02-01T14:50:06.000Z"}],["meta",{"property":"article:modified_time","content":"2025-04-10T23:49:50.000Z"}]]},"git":{"createdTime":1738392646000,"updatedTime":1744328990000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"bornforthis@bornforthis.cn","commits":5,"url":"https://github.com/AndersonHJB"}],"changelog":[{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"5473b5e3b3ee6ac00c5f598f9cd6bc06765e1d71","time":1738539767000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新DeepSeek R-1和OpenAI o3-mini文档，添加指向相关Medium文章的链接，提升信息获取的便利性"},{"hash":"a850025f31b63ec0482014fce627190184d09efd","time":1738496715000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"新增《如何在本地安装和使用DeepSeek R-1》文档，提供详细的安装步骤和使用指南；更新密码文档，增加推特相关内容"},{"hash":"da313dcf2806d69805f04ecf4b8c915ee809c495","time":1738392646000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"新增《如何在本地安装和使用DeepSeek R-1》文档，提供详细的安装步骤和使用指南，提升用户体验和实用性"}]},"readingTime":{"minutes":4.66,"words":1399},"filePathRelative":"blog/2025/Other/01-How-To-Install-And-Use-DeepSeek-R-1-In-Your-Local-PC.md","excerpt":"<figure><figcaption></figcaption></figure>\\n<p>everyone seems to be talking about <a href=\\"https://www.deepseek.com/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">DeepSeek</a> R-1, the new open-source AI language model made by a Chinese AI firm, DeepSeek. Some users claim it’s on par with, or even better than, OpenAI’s o1 in terms of reasoning capabilities.</p>","autoDesc":true}`),a={name:`01-How-To-Install-And-Use-DeepSeek-R-1-In-Your-Local-PC.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<figure><img src="/assets/1_zx-GHqEweCJGMsbrUPwF5A-DdnAf358.jpeg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>everyone seems to be talking about <a href="https://www.deepseek.com/" target="_blank" rel="noopener noreferrer">DeepSeek</a> R-1, the new open-source AI language model made by a Chinese AI firm, DeepSeek. Some users claim it’s on par with, or even better than, OpenAI’s o1 in terms of reasoning capabilities.</p><p>Currently, DeepSeek is free to use, which is great news for users, but it does raise some questions. With the surge in user volume, how are they managing the server costs?</p><p>Hardware running costs cannot be cheap, right?</p><p>The one logical here would be — data. Data is the lifeblood of AI models. They’re probably collecting user data in some way that benefits their quant trading model or for some other form of monetization.</p><p>So, if you’re concerned about data privacy but still still want to use R1 without sharing your data, the best way is to run the model locally.</p><h2 id="what-is-deepseek-r-1" tabindex="-1"><a class="header-anchor" href="#what-is-deepseek-r-1"><span>What is DeepSeek R-1?</span></a></h2><p>A couple of days back, Deepseek R-1 was unveiled as a fully open-sourced model, meaning anyone can take the underlying codebase, adapt it, and even fine-tune it to their own needs.</p><p>From a technical standpoint, Deepseek R-1 (often abbreviated as R1) stems from a large base model called DeepSeek-V3. The lab then refined this model through a combination of supervised fine-tuning (SFT) on high-quality human-labeled data and reinforcement learning (RL).</p><p>The result is a chatbot that can handle intricate prompts, reveal the reasoning steps behind complex questions (sometimes more transparently than other models), and even render code in the chat interface for quick testing.</p><p>It’s honestly very impressive, especially for a model that’s open-source.</p><h2 id="how-to-run-it-locally" tabindex="-1"><a class="header-anchor" href="#how-to-run-it-locally"><span><strong>How To Run It Locally</strong></span></a></h2><p>To run DeepSeek R-1 locally, we’ll be using a tool called <a href="https://ollama.com/" target="_blank" rel="noopener noreferrer">Ollama</a>.</p><p>Ollama is a free, open-source tool that allows users to run large language models (LLMs) locally on their computers. It is available for macOS, Linux, and Windows.</p><p>Head to the official Ollama website and click on the “Download” button. Install it on your system.</p><figure><img src="/assets/image-20250201143733319-BqcTAQTk.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>To confirm that the installation is successful, open a terminal and run the following command:</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">ollama</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -v</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><figure><img src="/assets/1_zTdFvWVP2Rs2GdaIlMCWYw-Deb03mf8.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>You should see the version number of the Ollama instead of an error.</p><p>Under the Models tab, search for the keyword “deepseek” and you should see the “deepseek-r1” on the first item on the search list.</p><figure><img src="/assets/image-20250201143937019-DNbVHF1l.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>Click on it and down the Models section, you’ll notice that there are multiple model sizes from 5 billion to 671 billion parameters. As a rule of thumb, larger models require more powerful GPUs to run.</p><ul><li><a href="https://ollama.com/library/deepseek-r1" target="_blank" rel="noopener noreferrer">https://ollama.com/library/deepseek-r1</a></li></ul><figure><img src="/assets/image-20250201144126577-DpbX2a9J.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>Smaller models like the 8 billion parameter version can run on GPUs with 8GB of VRAM. Larger models need significantly more resources (refer to the VRAM and GPU requirements section below).</p><p>To download and run the 8 billion parameter model, use the following command:</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">ollama</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> run</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> deepseek-r1:8b</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>The model will start downloading (around 4.9GB). Ensure you have enough disk space before proceeding.</p><figure><img src="/assets/1_gxvP-CwIT5GToQwYyMdTiw-D9zKqxX0.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>Once downloaded, the model will run locally on your machine. You can chat with it immediately.</p><figure><img src="/assets/1_tPN9mqSy9gGegy4G1DS04g-3cCRgKyp.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>Let’s test it with this example prompt:</p><figure><img src="/assets/1_49R_g2EpAUy--zMcnN2gUg-qS3gSCUv.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><blockquote><p><strong>Prompt:</strong> What is DeepSeek R-1?</p><p><strong>Response:</strong> DeepSeek-R-1 is an AI assistant developed by the Chinese company DeepSeek. It is designed to provide responses and assistance across a wide range of topics, including but not limited to mathematics, coding, natural language processing, and more. If you have any questions or need help with something, feel free to ask!</p></blockquote><p>Awesome. It’s fast and it still works even if I disconnect my laptop from the Wifi. Note that even if you are connected to the internet, it still cannot access the web.</p><figure><img src="/assets/1_Es2y3T-gjhHhluIHTLN2NQ-f07HCZiy.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><blockquote><p><strong>Prompt:</strong> What’s latest price of AAPL?</p><p><strong>Response:</strong> As an AI assistant, I don’t have real-time data access, so I can’t provide the latest stock price for Apple Inc. (AAPL). For the most accurate and up-to-date information, I recommend checking financial news platforms or your brokerage service.</p></blockquote><p><strong>Other things Ollama can do:</strong></p><h2 id="gpu-and-vram-requirements" tabindex="-1"><a class="header-anchor" href="#gpu-and-vram-requirements"><span>GPU and VRAM Requirements</span></a></h2><p>The VRAM requirements for DeepSeek-R1 depend on factors like model size, parameter count, and quantization techniques. Below is a detailed overview of the VRAM needs for DeepSeek-R1 and its distilled models, along with recommended GPUs:</p><figure><img src="/assets/1_506HP_2__HB_5jHpLHm-OQ-1KoV6oeu.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>Key notes on VRAM usage:</p><h2 id="why-run-it-locally" tabindex="-1"><a class="header-anchor" href="#why-run-it-locally"><span>Why Run It Locally?</span></a></h2><p>Sure, the web chatbot and mobile app for DeepSeek are free and incredibly convenient. You don’t need to set anything up, and features like DeepThink and web search are baked right in. But there are a few reasons why running it locally might be a better choice:</p><p><strong>Privacy</strong></p><p><strong>Offline Access</strong></p><p><strong>Future-Proofing</strong></p><p><strong>Flexibility</strong></p><h2 id="final-thoughts" tabindex="-1"><a class="header-anchor" href="#final-thoughts"><span>Final Thoughts</span></a></h2><p>At this point, it’s still unclear how DeepSeek handles user data. If you’re not too worried about data privacy, using the web or mobile app might be the way to go since they’re easier to use and offer features like DeepThink and web search. But if you’re someone who cares about where your data ends up, running the model locally is a good alternative to consider.</p><p>DeepSeek models are designed to run well even on hardware that isn’t super powerful. While larger models like DeepSeek-R1-Zero need distributed GPU setups, the distilled versions make it possible to run things smoothly on a single GPU with much lower requirements.</p><p>If you don’t like using the terminal, you can always add a simple UI with tools like <a href="https://github.com/AK391/ai-gradio" target="_blank" rel="noopener noreferrer">Gradio</a> or <a href="https://chatboxai.app/en" target="_blank" rel="noopener noreferrer">Chatbox AI</a>. I’ll write a guide on setting that up in the next article. For now, I hope this post helps you get started. Let me know your thoughts or if you’ve run into any issues, feel free to share them in the comments.</p><p>欢迎关注我公众号：AI悦创，有更多更好玩的等你发现！</p><details class="hint-container details"><summary>公众号：AI悦创【二维码】</summary><figure><img src="/gzh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure></details><div class="hint-container info"><p class="hint-container-title">AI悦创·编程一对一</p><p>AI悦创·推出辅导班啦，包括「Python 语言辅导班、C++ 辅导班、java 辅导班、算法/数据结构辅导班、少儿编程、pygame 游戏开发、Linux、Web 全栈」，全部都是一对一教学：一对一辅导 + 一对一答疑 + 布置作业 + 项目实践等。当然，还有线下线上摄影课程、Photoshop、Premiere 一对一教学、QQ、微信在线，随时响应！微信：Jiabcdefh</p><p>C++ 信息奥赛题解，长期更新！长期招收一对一中小学信息奥赛集训，莆田、厦门地区有机会线下上门，其他地区线上。微信：Jiabcdefh</p><p>方法一：<a href="http://wpa.qq.com/msgrd?v=3&amp;uin=1432803776&amp;site=qq&amp;menu=yes" target="_blank" rel="noopener noreferrer">QQ</a></p><p>方法二：微信：Jiabcdefh</p></div><figure><img src="/zsxq.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p><a href="https://medium.com/generative-ai/how-to-install-and-use-deepseek-r-1-in-your-local-pc-b77bc20f7566" target="_blank" rel="noopener noreferrer">.</a></p>`,58)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};